// Signs GET /n8n/overdue-loans. Signed string: `${timestamp}.GET./n8n/overdue-loans.` (empty body).
const crypto = require("crypto");

const secret = $env.N8N_TO_LENDLOOP_SECRET;
if (!secret) throw new Error("N8N_TO_LENDLOOP_SECRET is not configured in the n8n environment");

const PATH = "/n8n/overdue-loans";
const timestamp = Math.floor(Date.now() / 1000).toString();
const digest = crypto
  .createHmac("sha256", secret)
  .update(`${timestamp}.GET.${PATH}.`)
  .digest("hex");

return [{ json: { timestamp, signature: `v1=${digest}` } }];

// One item per overdue loan. An empty list ends the run (nothing to remind).
const { loans = [], asOf } = $input.first().json;
return loans.map((loan) => ({ json: { ...loan, asOf } }));

// Mock reminder: logs instead of emailing. Throws when the reminder cannot be
// sent, which routes the item to the "failed" branch and records reminder_failed.
// Set LENDLOOP_SIMULATE_REMINDER_FAILURE=true to demo the failure path.
if ($env.LENDLOOP_SIMULATE_REMINDER_FAILURE === "true") {
  throw new Error("Simulated reminder failure");
}
const loan = $json;
if (!loan.borrower.email) throw new Error("Borrower has no email on file");

const masked = loan.borrower.email.replace(/^(.).*(@.*)$/, "$1***$2");
const dayWord = loan.daysOverdue === 1 ? "day" : "days";
console.log(
  `[LendLoop mock reminder] to=${masked} "Hi ${loan.borrower.firstName}, the ${loan.tool.name} was due back ${loan.daysOverdue} ${dayWord} ago (${loan.endDate}). Please return it soon."`,
);

return {
  json: {
    writeback: {
      requestId: loan.requestId,
      kind: "reminder_sent",
      idempotencyKey: loan.idempotencyKey,
    },
  },
};

// Error branch of "Send reminder": record reminder_failed so the failure is
// visible on the loan in LendLoop. Uses the same idempotency key family with a
// ":failed" suffix, so a later successful retry is still recorded.
const loan = $("Split overdue loans").item.json;
const reason = ($json.error && ($json.error.message || $json.error)) || "Unknown error";

return {
  json: {
    writeback: {
      requestId: loan.requestId,
      kind: "reminder_failed",
      idempotencyKey: `${loan.idempotencyKey}:failed`,
      detail: String(reason).slice(0, 300),
    },
  },
};

// Signs a write-back to LendLoop: POST /n8n/automation-events.
// Signed string: `${timestamp}.POST./n8n/automation-events.${body}`.
// Runs once for each item; expects $json.writeback = { requestId, kind, idempotencyKey, detail? }.
const crypto = require("crypto");

const secret = $env.N8N_TO_LENDLOOP_SECRET;
if (!secret) throw new Error("N8N_TO_LENDLOOP_SECRET is not configured in the n8n environment");

const PATH = "/n8n/automation-events";
const body = JSON.stringify($json.writeback);
const timestamp = Math.floor(Date.now() / 1000).toString();
const digest = crypto
  .createHmac("sha256", secret)
  .update(`${timestamp}.POST.${PATH}.${body}`)
  .digest("hex");

return { json: { body, timestamp, signature: `v1=${digest}` } };
